import type { Usage } from "./groq.ts";

/**
 * groq/compound and groq/compound-mini are pass-through priced: each request
 * bills the underlying models it routed to, reported in usage_breakdown.
 * Rates are USD per million tokens (Groq list, mid-2026). On the free tier the
 * user pays nothing — this computes the real list value of what was consumed.
 */
const RATES: Array<{ match: RegExp; input: number; output: number }> = [
  { match: /llama-4-scout/i, input: 0.11, output: 0.34 },
  { match: /llama-4-maverick/i, input: 0.2, output: 0.6 },
  { match: /llama-3\.3-70b/i, input: 0.59, output: 0.79 },
  { match: /llama-3\.1-8b/i, input: 0.05, output: 0.08 },
  { match: /gpt-oss-120b/i, input: 0.15, output: 0.6 },
  { match: /gpt-oss-20b/i, input: 0.1, output: 0.5 },
  { match: /qwen/i, input: 0.29, output: 0.39 },
];

const FALLBACK = { input: 0.15, output: 0.6 };

export interface BreakdownEntry {
  model: string;
  usage: Usage;
}

function rateFor(model: string): { input: number; output: number } {
  return RATES.find((r) => r.match.test(model)) ?? FALLBACK;
}

export function costFromBreakdown(entries: BreakdownEntry[]): number {
  let total = 0;
  for (const e of entries) {
    const rate = rateFor(e.model);
    total +=
      (e.usage.prompt_tokens / 1e6) * rate.input +
      (e.usage.completion_tokens / 1e6) * rate.output;
  }
  return total;
}

export function costFromUsage(usage: Usage): number {
  return (usage.prompt_tokens / 1e6) * FALLBACK.input + (usage.completion_tokens / 1e6) * FALLBACK.output;
}

export function formatCost(usd: number): string {
  if (usd === 0) return "$0.00";
  if (usd < 0.01) return `$${usd.toFixed(4)}`;
  return `$${usd.toFixed(2)}`;
}
